#rf-root,.hf-root{--x3:#4d5347;font-family:var(--rf-font);color:var(--rf-text)}.stage{position:absolute;inset:0;animation:st-pushout 0.5s cubic-bezier(.76,0,.24,1) 2.5s both;}.cam{position:absolute;inset:0;}@keyframes st-cam{from{transform:scale(1)}to{transform:scale(1.02)}}.bd{position:absolute;inset:0;overflow:hidden;background:var(--rf-bg)}.tx{position:absolute;inset:0;background:var(--rf-surface);z-index:50}@keyframes st-rise{from{transform:translateY(120px)}to{transform:none}}
@keyframes st-pushin{from{transform:translateX(100%)}to{transform:none}}
@keyframes st-pushout{to{transform:translateX(-100%)}}
@keyframes st-zoomin{from{transform:scale(.92);opacity:0}to{transform:none;opacity:1}}
@keyframes st-zoomout{to{transform:scale(1.08);opacity:0}}
@keyframes st-fadein{from{opacity:0}to{opacity:1}}
@keyframes st-fadeout{to{opacity:0}}.rise{animation:k-rise .8s cubic-bezier(.16,1,.3,1) both}@keyframes k-rise{from{opacity:0;transform:translateY(40px)}to{opacity:1;transform:none}}
.pop{animation:k-pop .7s cubic-bezier(.16,1,.3,1) both}@keyframes k-pop{from{opacity:0;transform:scale(.94)}to{opacity:1;transform:none}}
.slide-l{animation:k-sl .8s cubic-bezier(.16,1,.3,1) both}@keyframes k-sl{from{opacity:0;transform:translateX(-80px)}to{opacity:1;transform:none}}
.slide-r{animation:k-sr .8s cubic-bezier(.16,1,.3,1) both}@keyframes k-sr{from{opacity:0;transform:translateX(80px)}to{opacity:1;transform:none}}
.fade{animation:k-fade .8s ease-out both}@keyframes k-fade{from{opacity:0}to{opacity:1}}.lt{display:inline-block;animation:lt-pop 0.6s cubic-bezier(.16,1,.3,1) both}
@keyframes lt-pop{from{opacity:0;transform:translateY(.35em)}to{opacity:1;transform:none}}.ly{position:absolute;inset:0}
.lw{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;text-align:center;padding:0 60px;font-size:230px;font-weight:600;letter-spacing:-.05em;line-height:.9;opacity:0;animation-name:lw;animation-fill-mode:both;animation-timing-function:linear}
.lw .lt{animation:none}
.lw.a{color:var(--rf-text)}.lw.b{color:var(--rf-text)}.lw.c{color:var(--rf-muted)}.lw.d{color:var(--rf-accent)}
@keyframes lw{0%{opacity:0;transform:translateY(80px)}14%{opacity:1;transform:none}86%{opacity:1;transform:none}100%{opacity:0;transform:translateY(-50px)}}
.lw.last{animation-name:lwl}@keyframes lwl{0%{opacity:0;transform:translateY(80px)}14%{opacity:1;transform:none}100%{opacity:1;transform:scale(1.04)}}
.eq{position:absolute;left:90px;right:90px;bottom:330px;height:140px;display:flex;align-items:flex-end;gap:8px}
.eq i{flex:1;height:100%;border-radius:4px;background:color-mix(in srgb,var(--rf-text) 28%,transparent);transform-origin:bottom;animation:eq ease-in-out infinite alternate both}
@keyframes eq{from{transform:scaleY(.12)}to{transform:scaleY(1)}}
.ft{position:absolute;left:0;right:0;top:260px;display:flex;justify-content:center;align-items:center;gap:14px;font:600 32px/1 "JetBrains Mono", "DejaVu Sans Mono", "Liberation Mono", monospace;color:var(--rf-muted)}

