.fade{animation:k-fade .8s ease-out both}@keyframes k-fade{from{opacity:0}to{opacity:1}}.wrap{position:absolute;left:90px;right:90px;top:0;bottom:0;display:flex;flex-direction:column;justify-content:center}.mk-l{display:block}.mk-w{display:inline-block;overflow:hidden;vertical-align:top;padding:0 .02em .08em;margin-bottom:-.08em}
.mk-w>span{display:inline-block;animation:mk-up 0.9s cubic-bezier(.16,1,.3,1) both}
@keyframes mk-up{from{transform:translateY(105%)}to{transform:none}}.eb{display:inline-block;font:500 32px/1.2 "JetBrains Mono", "DejaVu Sans Mono", "Liberation Mono", monospace;color:var(--rf-muted)}.flip{position:relative;height:620px;width:100%}
.flip span{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;font-size:640px;font-weight:600;letter-spacing:-.06em;line-height:1;opacity:0;animation-name:fl;animation-timing-function:cubic-bezier(.16,1,.3,1);animation-fill-mode:both}
@keyframes fl{0%{opacity:0;transform:translateY(60px)}25%{opacity:1;transform:none}80%{opacity:1;transform:none}100%{opacity:0;transform:translateY(-60px)}}
.flip .go{animation:k-pop .7s cubic-bezier(.16,1,.3,1) both;color:var(--rf-accent);opacity:1}.ctr{align-items:center;text-align:center}.ebw{margin-bottom:60px}
h2{margin:70px 0 0;font-size:88px;line-height:1;letter-spacing:-.04em;font-weight:var(--rf-heading-weight)}
.dt{display:flex;align-items:center;gap:18px;margin-top:40px;font:500 38px/1 "JetBrains Mono", "DejaVu Sans Mono", "Liberation Mono", monospace;color:var(--rf-muted)}
